// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Proxy c;

    function setUp() public {
        c = new Proxy();
    }

    function _run(bytes memory data, uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint beforeBal = address(this).balance;
        bool reverted;
        try c.forward(address(this), data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted && address(this).balance >= beforeBal);
    }

    function testFuzz_run(bytes memory data, uint256 amount) public {
        _run(data, amount);
    }

    receive() external payable {}

    fallback() external payable {}
}
